1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Both catalogue figures are read through this one row lookup, so an item's type
48	// is resolved against the catalogue in exactly one place.
49	const catalogueEntryFor = (item: Item) => CATALOGUE[item.type];
50	
51	// Totalling a catalogue column over a list of items is the same operation on the
52	// premium side and the claim side; only the column differs. Naming it once keeps
53	// the two columns visibly separate — which is the point: the building-block
54	// discount rewrites the basePremium column and never touches insuranceValue.
55	const totalOfColumn =
56	  (columnOf: (item: Item) => number) =>
57	  (items: Item[]): number =>
58	    items.reduce((total, item) => total + columnOf(item), 0);
59	
60	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
61	
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
66	  alikeItems.length === BLOCK_SIZE;
67	
68	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
69	
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_LEVEL = 5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
73	
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	
76	// An unenchanted item is enchantment 0, so every threshold reads the level the
77	// same way. The MHPCO sets several enchantment thresholds for different rules;
78	// each names its own level and compares through here.
79	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
80	
81	const carriesEnchantmentSurcharge = (item: Item): boolean =>
82	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
83	
84	// A rate table prices one subject: every row whose risk applies contributes its
85	// rate, and the total is their sum. Both the item surcharges and the policy-wide
86	// modifiers are rate tables — they differ only in what they are applied to.
87	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
88	
89	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
90	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
91	
92	// Every item-specific surcharge is a rate on THAT item's base premium, charged
93	// when its risk applies. Adding a new one means adding a row here — nothing else.
94	const ITEM_SURCHARGES: RateTable<Item> = [
95	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
96	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
97	];
98	
99	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
100	
101	const itemSurchargesOn = (items: Item[]): number =>
102	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
103	
104	// Items of the same type are "alike"; each group is priced together so a
105	// building block can be recognised.
106	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
107	  ...items
108	    .reduce(
109	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
110	      new Map<string, Item[]>(),
111	    )
112	    .values(),
113	];
114	
115	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
116	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
117	
118	const policyBaseOf = (items: Item[]): number =>
119	  alikeItemGroupsIn(items).reduce(
120	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
121	    0,
122	  );
123	
124	// Rounding always favours the MHPCO: premiums up, payouts down.
125	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
126	
127	const LOYALTY_YEARS = 2;
128	const LOYALTY_DISCOUNT_RATE = -0.2;
129	
130	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
131	
132	// Each item in a quote is treated as a first insurance regardless of customer
133	// history, so this surcharge is unconditional.
134	const appliesUnconditionally = (): boolean => true;
135	
136	const isLongStanding = ({ customer }: QuoteContext): boolean =>
137	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
138	
139	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
140	  precedingQuotes > 0;
141	
142	// A quote is priced from the customer plus its place in the scenario's history.
143	type QuoteContext = { customer: Customer; precedingQuotes: number };
144	
145	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
146	// base that already includes the item surcharges. Surcharges carry a positive
147	// rate, discounts a negative one. Adding a new one means adding a row here.
148	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
149	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
150	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
151	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
152	];
153	
154	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
155	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
156	
157	const quoteFor = (items: Item[], context: QuoteContext): Result => {
158	  const policyBase = policyBaseOf(items);
159	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
160	  return {
161	    premium: premiumRoundedInMHPCOsFavour(
162	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
163	    ),
164	  };
165	};
166	
167	const DEDUCTIBLE_PER_DAMAGE = 100;
168	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
169	
170	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
171	
172	// The insurance sum totals the value column over every insured item — one item,
173	// one row, no grouping. Blocks are a premium concept and cannot reach it.
174	const insuranceSumOf = totalOfColumn(insuranceValueOf);
175	
176	// A policy created by a quote step, tracked by that step's index so later claims
177	// can find it and draw down its cap.
178	type Policy = { items: Item[]; remainingCap: number };
179	
180	const policyFor = (items: Item[]): Policy => ({
181	  items,
182	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
183	});
184	
185	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
186	const HALF_REIMBURSEMENT_RATE = 0.5;
187	const FULL_REIMBURSEMENT_RATE = 1;
188	
189	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
190	// level: this one halves what a claim pays out, that one raises what a policy
191	// costs. They move independently — deliberately not shared.
192	const reimbursesOnlyHalf = (item: Item): boolean =>
193	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
194	
195	// How much of the damage the MHPCO reimburses, before the deductible bites.
196	const reimbursementRateFor = (item: Item): number =>
197	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
198	
199	// A damage names an item type; the policy holds the item it refers to. Which of
200	// several alike items is picked does not matter yet — no test distinguishes them.
201	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
202	  policy.items.find((item) => item.type === damage.itemType)!;
203	
204	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
205	  damage.amount * reimbursementRateFor(damagedItemIn(policy, damage));
206	
207	// The deductible bites once per damage, after the reimbursement rate is applied
208	// — never the other way round, which would pay out more.
209	const payoutForDamage = (damage: Damage, policy: Policy): number =>
210	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
211	
212	// One incident can damage several items; each damage is settled on its own
213	// (and so bears its own deductible), and the incident pays out their sum.
214	const payoutForIncident = (incident: Incident, policy: Policy): number =>
215	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
216	
217	// A payout is drawn from the policy's cap, leaving less for later claims.
218	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
219	  ...policy,
220	  remainingCap: policy.remainingCap - payout,
221	});
222	
223	// Settling a claim pays out and draws the cap down by the same amount, so the
224	// result the customer sees is the payout plus the cap that payout left behind.
225	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
226	  const payout = payoutForIncident(incident, policy);
227	  const settledPolicy = capDrawnDownBy(policy, payout);
228	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
229	};
230	
231	// What the scenario has accumulated before the current step: the results so far,
232	// the history a quote is priced against, and the policies earlier quotes created.
233	type ScenarioState = {
234	  results: Result[];
235	  precedingQuotes: number;
236	  policies: Record<number, Policy>;
237	};
238	
239	const INITIAL_SCENARIO_STATE: ScenarioState = {
240	  results: [],
241	  precedingQuotes: 0,
242	  policies: {},
243	};
244	
245	// Every step reports exactly one result, so recording it is the one thing the
246	// two step kinds always have in common — named once here rather than rebuilt in
247	// each of them.
248	const withResultRecorded = (state: ScenarioState, result: Result): ScenarioState => ({
249	  ...state,
250	  results: [...state.results, result],
251	});
252	
253	const afterQuote = (
254	  state: ScenarioState,
255	  items: Item[],
256	  customer: Customer,
257	  stepIndex: number,
258	): ScenarioState => ({
259	  ...withResultRecorded(
260	    state,
261	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
262	  ),
263	  precedingQuotes: state.precedingQuotes + 1,
264	  policies: { ...state.policies, [stepIndex]: policyFor(items) },
265	});
266	
267	const afterClaim = (
268	  state: ScenarioState,
269	  policyIndex: number,
270	  incident: Incident,
271	): ScenarioState => {
272	  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
273	  return {
274	    ...withResultRecorded(state, result),
275	    policies: { ...state.policies, [policyIndex]: settledPolicy },
276	  };
277	};
278	
279	const afterStep = (
280	  state: ScenarioState,
281	  step: Step,
282	  customer: Customer,
283	  stepIndex: number,
284	): ScenarioState =>
285	  step.op === "quote"
286	    ? afterQuote(state, step.items, customer, stepIndex)
287	    : afterClaim(state, step.policy, step.incident);
288	
289	export const runScenario = (scenario: Scenario): { results: Result[] } => {
290	  const { results } = scenario.steps.reduce(
291	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
292	    INITIAL_SCENARIO_STATE,
293	  );
294	  return { results };
295	};
